"use strict";(self.webpackChunksite=self.webpackChunksite||[]).push([[567],{5226:e=>{e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"docsSidebar":[{"type":"link","href":"/","label":"PlanetsLib","docId":"intro","unlisted":false},{"type":"category","label":"Usage documentation","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/usage-documentation/asteroid-helpers","label":"Asteroid Spawn Helpers","docId":"usage-documentation/asteroid-helpers","unlisted":false},{"type":"link","href":"/usage-documentation/entity-fields","label":"Entity Fields","docId":"usage-documentation/entity-fields","unlisted":false},{"type":"link","href":"/usage-documentation/entity-replacement-system","label":"Entity Replacement System","docId":"usage-documentation/entity-replacement-system","unlisted":false},{"type":"link","href":"/usage-documentation/event-handler","label":"Event Handler","docId":"usage-documentation/event-handler","unlisted":false},{"type":"link","href":"/usage-documentation/ground-diggers","label":"Ground Diggers","docId":"usage-documentation/ground-diggers","unlisted":false},{"type":"link","href":"/usage-documentation/icon-helpers","label":"Icon Helpers","docId":"usage-documentation/icon-helpers","unlisted":false},{"type":"link","href":"/usage-documentation/orbit-graphics","label":"Orbit Graphics","docId":"usage-documentation/orbit-graphics","unlisted":false},{"type":"link","href":"/usage-documentation/planet-properties","label":"Special Planet Properties","docId":"usage-documentation/planet-properties","unlisted":false},{"type":"link","href":"/usage-documentation/recipe-events","label":"Recipe Events","docId":"usage-documentation/recipe-events","unlisted":false},{"type":"link","href":"/usage-documentation/remote-interfaces","label":"Remote Interfaces","docId":"usage-documentation/remote-interfaces","unlisted":false},{"type":"link","href":"/usage-documentation/rocket-part-recipes","label":"Rocket Part Recipes","docId":"usage-documentation/rocket-part-recipes","unlisted":false},{"type":"link","href":"/usage-documentation/technologies","label":"Science & Technologies","docId":"usage-documentation/technologies","unlisted":false}],"href":"/category/usage-documentation"},{"type":"link","href":"/player-facing-features","label":"Player Facing Features","docId":"player-facing-features","unlisted":false}]},"docs":{"intro":{"id":"intro","title":"PlanetsLib","description":"Code and graphics to help modders creating planets, moons and other systems. This library is a community project. Anyone is welcome to open a pull request on Github. For feature requests, please open an issue. For general discussion, use Discord.","sidebar":"docsSidebar"},"player-facing-features":{"id":"player-facing-features","title":"Player Facing Features","description":"The primary intent of PlanetsLib is to be a library which provides opt-in functionality for other mods. However, a small number of game-affecting or player-interface-affecting features have been added over time. These are listed below, player feedback on them is most welcome in Discord.","sidebar":"docsSidebar"},"usage-documentation/asteroid-helpers":{"id":"usage-documentation/asteroid-helpers","title":"Asteroid Spawn Helpers","description":"PlanetsLib provides data-stage helpers for building asteroidspawndefinitions on planets, space locations and space connections. They are designed for the common planet-mod setup:","sidebar":"docsSidebar"},"usage-documentation/entity-fields":{"id":"usage-documentation/entity-fields","title":"Entity Fields","description":"* [[EntityPrototype]]::placeableby. This field only affects pipette behavior, and does not make this entity placeable by the entity\'s pipette result. A wrapper for PlanetsLib.constants.pipetteresult. In data-final-fixes, manipulate this mod-data table directly.","sidebar":"docsSidebar"},"usage-documentation/entity-replacement-system":{"id":"usage-documentation/entity-replacement-system","title":"Entity Replacement System","description":"PlanetsLib allows you to quickly generate planet-exclusive variants of entities. On placing an entity on a planet with a planet-exclusive variant, PlanetsLib will replace the original entity with your variant. The difference between entity variants and the original entity are invisible to the user, and variants can not be seen in the Factoriopedia. Every variant must be associated with a boolean startup setting that can be disabled to ease in uninstallation. Once an entity variant has been created, any attempt to create a variant for the same entity for the same planet will throw an error. This is a limitation of the current system that may change in the future. Currently, entity variants that are the same type as their origin entity are well-tested, but changing entity types is untested.","sidebar":"docsSidebar"},"usage-documentation/event-handler":{"id":"usage-documentation/event-handler","title":"Event Handler","description":"Planetslib provides an alternative to the event handler library found in factorio\'s core mod, the core of the code was taken from there then extended. It does work as a drop in replacement for that.","sidebar":"docsSidebar"},"usage-documentation/ground-diggers":{"id":"usage-documentation/ground-diggers","title":"Ground Diggers","description":"PlanetsLib can convert mining drills into ground diggers: machines that dig up a recipe\'s products anywhere on a planet, even where no resources exist. This is useful for planets where the surface itself is a resource (for example, regolith on a moon).","sidebar":"docsSidebar"},"usage-documentation/icon-helpers":{"id":"usage-documentation/icon-helpers","title":"Icon Helpers","description":"PlanetsLib provides helpers for composing and modifying prototype icons\u2014the icons field, which is an array of [IconData]] entries. These helpers are data-stage only, and are ported from [\\"Muluna, Moon of Nauvis\\".","sidebar":"docsSidebar"},"usage-documentation/orbit-graphics":{"id":"usage-documentation/orbit-graphics","title":"Orbit Graphics","description":"Moon orbit graphics","sidebar":"docsSidebar"},"usage-documentation/planet-properties":{"id":"usage-documentation/planet-properties","title":"Special Planet Properties","description":"PlanetsLib allows the addition of \\"special properties\\", values which can be displayed as surface properties, but are not intended to be used as surface properties. These properties are used during data-final-fixes and in control scripts to execute certain behavior.","sidebar":"docsSidebar"},"usage-documentation/recipe-events":{"id":"usage-documentation/recipe-events","title":"Recipe Events","description":"PlanetsLib includes one event that recipes can hook into using RecipePrototype::PlanetsLibrecipeeffects. This event adds items to the machine\'s ingredient inventory on craft. Additional events may be added in the future.","sidebar":"docsSidebar"},"usage-documentation/remote-interfaces":{"id":"usage-documentation/remote-interfaces","title":"Remote Interfaces","description":"Storage extraction and transfer","sidebar":"docsSidebar"},"usage-documentation/rocket-part-recipes":{"id":"usage-documentation/rocket-part-recipes","title":"Rocket Part Recipes","description":"You can use the library to assign unique rocket part recipes to rocket silos placed on a specified planet to increase or decrease the difficulty of launching rockets on the planet. Rocket silos with their recipe fixed to the vanilla rocket-part recipe are targeted by PlanetsLib. To implement:","sidebar":"docsSidebar"},"usage-documentation/technologies":{"id":"usage-documentation/technologies","title":"Science & Technologies","description":"* PlanetsLib.getchildtechnologies(techname) \u2014 Returns a list of the names of all technologies that have techname as a prerequisite. Throws an error if tech_name is not a valid technology.","sidebar":"docsSidebar"}}}}')}}]);